(async()=>{const expected='1.0.7';
const urls=["https://cdn.jsdelivr.net/gh/AliceNekoqqq/Aliceneko-Opening-Selector@16f09fa73e10332b6313cd60ddb816546bc53eec/remote.js","https://testingcf.jsdelivr.net/gh/AliceNekoqqq/Aliceneko-Opening-Selector@16f09fa73e10332b6313cd60ddb816546bc53eec/remote.js","https://raw.githubusercontent.com/AliceNekoqqq/Aliceneko-Opening-Selector/16f09fa73e10332b6313cd60ddb816546bc53eec/remote.js"];
let loaded=false;const errors=[];
for(const url of urls){try{const module=await import(url);if(module.OPENING_SELECTOR_VERSION!==expected)throw Error('版本不符');module.mountUniversalSelector(globalThis.$?.('body')?.[0]?.ownerDocument||document,globalThis.TavernHelper||(typeof globalThis.getChatMessages==='function'?globalThis:null));loaded=true;break}catch(error){errors.push(String(error?.message||error))}}
if(!loaded){const message='红豆粉开场白选择器 '+expected+' 加载失败：'+errors.join(' | ');console.error(message);globalThis.toastr?.error?.(message)}})();
